import React, { useEffect, useState, useRef } from "react";
import axios from "axios";
import { Line } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement);

function App() {
  const [data, setData] = useState([]);
  const [page, setPage] = useState("dashboard");
  const [loading, setLoading] = useState(true);

  const videoRef = useRef(null);
  const canvasRef = useRef(null);

  // ================= LOAD DATA =================
  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 3000);
    return () => clearInterval(interval);
  }, []);

  const loadData = async () => {
  try {
    const res = await axios.get("http://127.0.0.1:8000/data");

    console.log("DATA MASUK:", res.data); // DEBUG

    setData(res.data);   // ❗ LANGSUNG SET
    setLoading(false);

  } catch (err) {
    console.log("ERROR API:", err);
    setLoading(false);
  }
};

  const latest = data.length > 0 ? data[0] : null;
  if (!latest) {
  return <h2>Data kosong / belum masuk</h2>;
}
  // ================= CAMERA =================
  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: true
      });

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }

    } catch (err) {
      console.log("CAMERA ERROR:", err);
      alert("Izinkan kamera dulu!");
    }
  };

  // ================= DETECT =================
  const sendFrame = async () => {
    if (!videoRef.current || !canvasRef.current) return;

    const tempCanvas = document.createElement("canvas");
    tempCanvas.width = 640;
    tempCanvas.height = 480;

    const ctx = tempCanvas.getContext("2d");
    ctx.drawImage(videoRef.current, 0, 0, 640, 480);

    const blob = await new Promise(resolve =>
      tempCanvas.toBlob(resolve, "image/jpeg")
    );

    const formData = new FormData();
    formData.append("file", blob, "frame.jpg");

    try {
      const res = await axios.post("http://127.0.0.1:8000/detect", formData);

      drawBoxes(res.data.boxes || []);

    } catch (err) {
      console.log("ERROR DETECT:", err);
    }
  };

  // ================= LOOP =================
  useEffect(() => {
    if (page !== "monitoring") return;

    const interval = setInterval(() => {
      sendFrame();
    }, 1500);

    return () => clearInterval(interval);
  }, [page]);

  // ================= DRAW BOX =================
  const drawBoxes = (boxes) => {
    if (!canvasRef.current) return;

    const ctx = canvasRef.current.getContext("2d");

    ctx.clearRect(0, 0, 640, 480);

    ctx.strokeStyle = "lime";
    ctx.lineWidth = 3;

    boxes.forEach(box => {
      ctx.strokeRect(
        box.x1,
        box.y1,
        box.x2 - box.x1,
        box.y2 - box.y1
      );
    });
  };

  // ================= CHART =================
  const chartData = {
    labels: data.map(d => d.waktu).reverse(),
    datasets: [
      {
        label: "Jumlah Orang",
        data: data.map(d => d.jumlah_orang).reverse(),
        borderColor: "#22c55e"
      }
    ]
  };

  const getColor = (kondisi) => {
    if (kondisi === "PEMBOROSAN") return "red";
    if (kondisi === "PERINGATAN") return "orange";
    return "#22c55e";
  };

  return (
    <div style={{ display: "flex", minHeight: "100vh", background: "#0f172a", color: "white" }}>

      {/* SIDEBAR */}
      <div style={{ width: 220, background: "#1e293b", padding: 20 }}>
        <h2>⚡ Hematrik</h2>
        <p onClick={() => setPage("dashboard")}>Dashboard</p>
        <p onClick={() => setPage("monitoring")}>Monitoring</p>
        <p onClick={() => setPage("history")}>History</p>
      </div>

      {/* CONTENT */}
      <div style={{ flex: 1, padding: 30 }}>



        {/* DASHBOARD */}
        {!loading && page === "dashboard" && latest && (
          <>
            <h1>📊 Dashboard Monitoring</h1>

            <div style={{
              padding: 15,
              borderRadius: 10,
              background: getColor(latest.kondisi)
            }}>
              {latest.notifikasi}
            </div>

            <div style={{ display: "flex", gap: 20, marginTop: 20 }}>
              <div style={card}><h3>People</h3><h1>{latest.jumlah_orang}</h1></div>
              <div style={card}><h3>Listrik</h3><h1>{latest.status_listrik}</h1></div>
              <div style={card}>
                <h3>Kondisi</h3>
                <h1 style={{ color: getColor(latest.kondisi) }}>
                  {latest.kondisi}
                </h1>
              </div>
            </div>

            <div style={{ marginTop: 30 }}>
              <Line data={chartData} />
            </div>
          </>
        )}

        {/* MONITORING */}
        {page === "monitoring" && (
          <>
            <h1>📷 Live CCTV AI</h1>

            <button onClick={startCamera} style={{ marginBottom: 15 }}>
              Start Camera
            </button>

            <div style={{ position: "relative", width: 640 }}>
              <video
                ref={videoRef}
                autoPlay
                playsInline
                muted
                style={{
                  width: "640px",
                  height: "480px",
                  background: "black",
                  borderRadius: 10
                }}
              />

              <canvas
                ref={canvasRef}
                width={640}
                height={480}
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0
                }}
              />
            </div>
          </>
        )}

        {/* HISTORY */}
        {page === "history" && (
          <>
            <h1>📜 History</h1>

            <table style={{ width: "100%", marginTop: 20 }}>
              <thead>
                <tr>
                  <th>Waktu</th>
                  <th>Orang</th>
                  <th>Listrik</th>
                  <th>Kondisi</th>
                </tr>
              </thead>

              <tbody>
                {data.map(d => (
                  <tr key={d.id}>
                    <td>{d.waktu}</td>
                    <td>{d.jumlah_orang}</td>
                    <td>{d.status_listrik}</td>
                    <td style={{ color: getColor(d.kondisi) }}>
                      {d.kondisi}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </>
        )}

      </div>
    </div>
  );
}

const card = {
  background: "#1e293b",
  padding: 20,
  borderRadius: 10
};

export default App;
